// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Proxy} from "../src/Proxy.sol";

contract InvMutTest is Test {
    Proxy c;
    function setUp() public { c = new Proxy(); }

    // fuzzed param: whether the helper callee should revert when called
    function testFuzz_property(bool shouldRevert) public {
        // deploy a helper that either reverts or succeeds based on shouldRevert
        CalleeHelper helper = new CalleeHelper(shouldRevert);

        // attempt the external entry; capture whether it succeeded
        bool ok;
        try c.forward(address(helper), "0x") {
            ok = true;
        } catch {
            ok = false;
        }

        // GENERAL RULE (one assert): If the callee reverts, the reference C ALWAYS reverts when forwarding to it.
        // The mutant flips the checked success flag and will NOT revert when the callee failed, so for shouldRevert==true
        // the mutant yields ok==true while the reference yields ok==false. Therefore we assert that when the helper is
        // configured to revert, the call did not succeed (ok == false). This holds for the reference for all inputs,
        // and is violated by the mutant for some input (shouldRevert == true).
        assertTrue(!shouldRevert || ok == false);
    }
}

contract CalleeHelper {
    bool public shouldRevert;
    constructor(bool _shouldRevert) {
        shouldRevert = _shouldRevert;
    }
    // accept any calldata; if configured, revert, otherwise succeed
    fallback() external payable {
        if (shouldRevert) revert("revert-from-helper");
    }
    receive() external payable {
        if (shouldRevert) revert("revert-from-helper");
    }
}
